{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Pentosan polysulfate sodium, a highly sulfated polysaccharide, had oral bioavailability of only 0.5–1% in healthy subjects, directly supporting low bioavailability for sulfated carbohydrate structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Dextran sulfate, another sulfated polysaccharide, has poor oral bioavailability in humans, supporting low for highly sulfated sugars.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zanamivir, a polar sialic-acid-like carbohydrate with multiple hydroxyls and ionizable groups, has absolute oral bioavailability of 2% (range 1–5%) in volunteers, supporting low for polar carbohydrate drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Acamprosate, a small sulfonate, has absolute oral bioavailability of ~11% under fasting conditions, supporting low for sulfonate-containing polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Glucoraphanin, a glucosinolate with a sulfate and sugar moiety, had mean oral bioavailability of 5% (range 1–45%) in humans, supporting low for polar glycoside sulfates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Levovirin, a highly polar nucleoside, has ~10% oral bioavailability in humans, supporting low for polar carbohydrate-like drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ginsenoside Rg3, a glycoside with multiple sugar units, has low oral bioavailability in humans, supporting low for polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Furosemide acyl glucuronide, a glucuronide conjugate, had oral bioavailability of 0.15 in humans, supporting low for glucuronide/sulfate conjugates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tobramycin, an aminoglycoside with multiple polar amino and hydroxy groups, has negligible oral bioavailability, supporting low for highly polar aminosugars.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Oseltamivir carboxylate, the polar active metabolite, has <5% oral bioavailability when given directly, supporting low for polar carboxylate-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Oseltamivir carboxylate shows ~79% absolute bioavailability after oral administration of the lipophilic prodrug oseltamivir, but this high value depends on prodrug absorption and is not transferable to the non-prodrug query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, sulfated N-acetylhexosamine-glucuronic acid disaccharide. Multiple high-transfer experimental analogues—sulfated polysaccharides, polar sialic acid analogs, sulfonates, glucuronides, and aminoglycosides—show oral bioavailability well below 20% (0.5–11%). The only high-bioavailability evidence comes from oseltamivir carboxylate after administration of its lipophilic prodrug, which is not applicable to the query. Therefore predict low.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for the exact query molecule.",
    "Active uptake/transporter effects cannot be fully excluded, though passive permeability is expected to be negligible.",
    "Prodrug strategies could improve bioavailability, but the query is not a prodrug."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

